class Solution:
    def minCosts(self, cost: List[int]) -> List[int]:
        dp = [0] * len(cost)
        if len(cost) > 1:
            dp[-1] = cost[-1]
            dp[-2] = cost[-2] + dp[-1]
        else:
            return cost

        for i in range(len(cost)-3, -1, -1):
            dp[i] = cost[i] + min(dp[i+2], dp[i+1])

        return dp

