        n = len(cost)
        dp = [float('inf')] * (n + 1)
        dp[n] = 0

        for i in range(n - 1, -1, -1):
            dp[i] = min(dp[i + 1], cost[i] + dp[i + 2])

        return dp[0]

class Solution:
    def minCosts(self, cost: List[int]) -> List[int]:
        n = len(cost)
        dp = [float('inf')] * n

        # Base case: cost[0] is always 0
        dp[0] = 0

        # Fill the DP table
        for i in range(1, n):
            dp[i] = cost[i] + min(dp[i-1], dp[i-2])

        return dp[n-1]

