class Solution:
    def minCosts(self, cost: List[int]) -> List[int]:
        # Initialize the result list with the last element of the input list
        res = [cost[-1]]

        # Iterate through the input list starting from the second last element
        for i in range(len(cost)-2, -1, -1):
            # Calculate the minimum cost to reach the current position
            if i % 2 == 0:
                # If the current position is even, take the minimum of the current cost plus the cost of the next odd position
                res.append(min(cost[i], cost[i+1]+res[-1]))
            else:
                # If the current position is odd, take the minimum of the current cost plus the cost of the previous even position
                res.append(min(cost[i], cost[i-1]+res[-1]))

        # Return the result list
        return res

