class Solution:
    def minCosts(self, cost: List[int]) -> List[int]:
        # Initialize two variables to keep track of the minimum costs to reach positions 0 and 1
        min_cost_0 = min_cost_1 = 0

        # Iterate through the cost list starting from the second element
        for i in range(1, len(cost)):
            # Update the minimum cost to reach position i based on the previous minimum costs
            if i % 2 == 0:
                min_cost_i = min(min_cost_0 + cost[i], min_cost_1)
            else:
                min_cost_i = min(min_cost_0, min_cost_1 + cost[i])

            # Update the previous minimum costs for the next iteration
            min_cost_0, min_cost_1 = min_cost_1, min_cost_i

        # Return the minimum cost to reach position n-1
        return [min_cost_0]

