def check_permutation(A):
    # Check if there exists a permutation B such that B[0] * B[1] = B[2]
    for i in range(len(A)):
        for j in range(i+1, len(A)):
            for k in range(j+1, len(A)):
                if A[i] * A[j] == A[k]:
                    return "Yes"
    return "No"

