class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Count the number of '1's in the original string
        ones_count = sum(1 for char in s if char == '1')

        # If there are no '1's, return 0
        if ones_count == 0:
            return 0

        # Initialize variables to keep track of the current count of '1's and the result
        current_ones = 0
        result = 0

        # Iterate through the string
        for char in s:
            if char == '1':
                current_ones += 1
                result = max(result, current_ones)
            else:
                current_ones = 0

        # Return the result plus one (to account for the augmented '1's)
        return result + 1

