class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Initialize variables
        n = len(s)
        dp = [0] * (n + 2)  # DP array to store the maximum number of active sections

        # Iterate through each character in the string
        for i in range(n):
            if s[i] == '1':
                # If the current character is '1', update the DP array
                dp[i + 2] = dp[i + 1] + 1
                if i > 0 and s[i - 1] == '0':
                    dp[i + 2] += 1
                if i < n - 1 and s[i + 1] == '0':
                    dp[i + 2] += 1
            else:
                # If the current character is '0', reset the DP array
                dp[i + 2] = 0

        # Return the maximum value from the DP array
        return max(dp)

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ans, cnt, i = 0, 0, 0
        while i < len(s):
            # If we encounter a '0', reset the counter
            if s[i] == '0':
                cnt = 0
            else:
                # Increment the counter for each consecutive '1'
                cnt += 1
                # Update the answer with the maximum value found so far
                ans = max(ans, cnt)
            i += 1
        return ans

