    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        dp = [0] * (n+1)

        for i in range(1, n):
            if s[i-1] == '0':
                dp[i] = dp[i-1]
            else:
                dp[i] = dp[i-1] + 1

        ans = 0
        for i in range(n-1, -1, -1):
            if s[i+1] == '0':
                dp[i] = max(dp[i], dp[i+1])
            else:
                dp[i] = max(dp[i], dp[i+1] - 1)

            ans = max(ans, dp[i])

        return ans

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Initialize variables
        res = 0
        left = 0

        # Iterate through the string
        for right in range(len(s)):
            # If we encounter '1', add to result and move left pointer to right+1
            if s[right] == '1':
                res += 1
                left = right + 1

            # After processing a block of '1's, check if it was surrounded by '0's
            # If yes, convert the block to '0's and update left pointer to right+2
            else:
                if left < right:
                    res -= (right - left)
                    left = right + 1

        return res

