class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Augment the input string with '1' at both ends
        augmented_s = '1' + s + '1'
        n = len(augmented_s)
        dp = [0] * n

        for i in range(1, n - 1):
            if augmented_s[i] == '0':
                # If the current character is '0', check the previous and next characters
                if augmented_s[i - 1] == '0' and augmented_s[i + 1] == '0':
                    # If both adjacent characters are '0', set the current DP value to 1
                    dp[i] = 1
                elif augmented_s[i - 1] == '1' and augmented_s[i + 1] == '1':
                    # If both adjacent characters are '1', set the current DP value to the sum of the previous two DP values
                    dp[i] = dp[i - 1] + dp[i - 2]

        return dp[-1]

