class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        rows, cols = len(grid), len(grid[0])
        directions = [(0, 1), (-1, 0)]  # Right, Down

        def dfs(x, y, direction):
            if not (0 <= x < rows and 0 <= y < cols):
                return
            result.append(grid[x][y])
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if (nx, ny) != (x, y):
                    dfs(nx, ny, direction)

        for i in range(rows):
            if i % 2 == 0:
                dfs(i, 0, directions[0])  # Right traversal
            else:
                dfs(i, cols - 1, directions[1])  # Left traversal

        return result

