class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        rows, cols = len(grid), len(grid[0])
        res = []
        i, j = 0, 0

        while i < rows and j < cols:
            # Traverse right
            for _ in range(cols):
                res.append(grid[i][j])
                j += 1
                if j >= cols or i >= rows:
                    break

            # Traverse down
            for _ in range(rows):
                res.append(grid[i][j])
                i += 1
                if j >= cols or i >= rows:
                    break

            # Adjust direction
            if i % 2 == 0:
                j -= 1
            else:
                j += 1

        return res

