def find_matching_subsequences(A, B, a):
    # Initialize a set to store the subsequences
    subsequences = set()

    # Generate all possible subsequences of A that start with a
    for i in range(len(A)):
        if A[i] == a:
            # Recursively find all subsequences of A starting with a
            for subseq in find_matching_subsequences(A[i+1:], B, a):
